  'elevators_in_block_a_b_will_undergo_quarterly_preventive_maintenance_this_saturday_from_10_am_to_1_pm': 'ಬ್ಲಾಕ್ ಎ ಮತ್ತು ಬಿ ನಲ್ಲಿರುವ ಲಿಫ್ಟ್‌ಗಳು ಈ ಶನಿವಾರ ಬೆಳಿಗ್ಗೆ 10 ರಿಂದ ಮಧ್ಯಾಹ್ನ 1 ರವರೆಗೆ ತ್ರೈಮಾಸಿಕ ತಡೆಗಟ್ಟುವ ನಿರ್ವಹಣೆಗೆ ಒಳಗಾಗುತ್ತವೆ.',
  'welcome_to_greenfield_heights_community': 'ಗ್ರೀನ್‌ಫೀಲ್ಡ್ ಹೈಟ್ಸ್ ಸಮುದಾಯಕ್ಕೆ ಸ್ವಾಗತ',
  'we_are_delighted_to_welcome_all_residents_please_reach_out_to_management_for_any_facility_requests': 'ಎಲ್ಲಾ ನಿವಾಸಿಗಳನ್ನು ಸ್ವಾಗತಿಸಲು ನಾವು ಸಂತೋಷಪಡುತ್ತೇವೆ! ಯಾವುದೇ ಸೌಲಭ್ಯದ ವಿನಂತಿಗಳಿಗಾಗಿ ದಯವಿಟ್ಟು ನಿರ್ವಹಣೆಯನ್ನು ಸಂಪರ್ಕಿಸಿ.',
  'pool_maintenance_20_july_2026': 'ಪೂಲ್ ನಿರ್ವಹಣೆ – 20 ಜುಲೈ 2026',
  'the_swimming_pool_will_remain_closed_on_20th_july_2026_for_annual_chlorination_and_tile_maintenance_we_apologize_for_the_inconvenience': 'ವಾರ್ಷಿಕ ಕ್ಲೋರಿನೇಶನ್ ಮತ್ತು ಟೈಲ್ ನಿರ್ವಹಣೆಗಾಗಿ 20 ಜುಲೈ 2026 ರಂದು ಈಜುಕೊಳವನ್ನು ಮುಚ್ಚಲಾಗುತ್ತದೆ. ಅನಾನುಕೂಲತೆಗಾಗಿ ನಾವು ಕ್ಷಮೆಯಾಚಿಸುತ್ತೇವೆ.',
  'independence_day_celebration_15_august_2026': 'ಸ್ವಾತಂತ್ರ್ಯ ದಿನಾಚರಣೆ – 15 ಆಗಸ್ಟ್ 2026',
  'greenfield_heights_community_cordially_invites_all_residents_to_the_independence_day_celebration_at_the_clubhouse_main_hall_at_8_00_am': 'ಗ್ರೀನ್‌ಫೀಲ್ಡ್ ಹೈಟ್ಸ್ ಸಮುದಾಯವು ಬೆಳಿಗ್ಗೆ 8:00 ಗಂಟೆಗೆ ಕ್ಲಬ್‌ಹೌಸ್ ಮುಖ್ಯ ಸಭಾಂಗಣದಲ್ಲಿ ನಡೆಯುವ ಸ್ವಾತಂತ್ರ್ಯ ದಿನಾಚರಣೆಗೆ ಎಲ್ಲಾ ನಿವಾಸಿಗಳನ್ನು ಪ್ರೀತಿಯಿಂದ ಆಹ್ವಾನಿಸುತ್ತದೆ.',
  'scheduled_power_outage_18_july_2026_block_b': 'ನಿಗದಿತ ವಿದ್ಯುತ್ ಕಡಿತ – 18 ಜುಲೈ 2026 (ಬ್ಲಾಕ್ ಬಿ)',
  'electrical_board_maintenance_scheduled_for_block_b_apartments_on_18_july_between_10_am_2_pm_generator_backup_will_be_available_for_common_areas': 'ಬ್ಲಾಕ್ ಬಿ ಅಪಾರ್ಟ್‌ಮೆಂಟ್‌ಗಳಿಗೆ ಜುಲೈ 18 ರಂದು ಬೆಳಿಗ್ಗೆ 10 ರಿಂದ ಮಧ್ಯಾಹ್ನ 2 ರ ನಡುವೆ ವಿದ್ಯುತ್ ಮಂಡಳಿ ನಿರ್ವಹಣೆಯನ್ನು ನಿಗದಿಪಡಿಸಲಾಗಿದೆ. ಸಾಮಾನ್ಯ ಪ್ರದೇಶಗಳಿಗೆ ಜನರೇಟರ್ ಬ್ಯಾಕಪ್ ಲಭ್ಯವಿರುತ್ತದೆ.',
  'monthly_agm_25_july_2026': 'ಮಾಸಿಕ ಎಜಿಎಂ – 25 ಜುಲೈ 2026',
  'annual_general_meeting_for_q2_2026_financial_review_agenda_budget_approval_security_upgrade_proposal_amenity_booking_policy_update': 'Q2 2026 ಆರ್ಥಿಕ ಪರಿಶೀಲನೆಗಾಗಿ ವಾರ್ಷಿಕ ಸಾಮಾನ್ಯ ಸಭೆ. ಕಾರ್ಯಸೂಚಿ: ಬಜೆಟ್ ಅನುಮೋದನೆ, ಭದ್ರತಾ ಅಪ್‌ಗ್ರೇಡ್ ಪ್ರಸ್ತಾವನೆ, ಸೌಲಭ್ಯ ಬುಕಿಂಗ್ ನೀತಿ ನವೀಕರಣ.',
  'lift_inspection_block_c_22_july_2026': 'ಲಿಫ್ಟ್ ತಪಾಸಣೆ – ಬ್ಲಾಕ್ ಸಿ – 22 ಜುಲೈ 2026',
  'government_mandated_elevator_inspection_for_block_c_lifts_expected_completion_4_hours_stairways_accessible_at_all_times': 'ಬ್ಲಾಕ್ ಸಿ ಲಿಫ್ಟ್‌ಗಳಿಗಾಗಿ ಸರ್ಕಾರಿ ಕಡ್ಡಾಯ ಲಿಫ್ಟ್ ತಪಾಸಣೆ. ನಿರೀಕ್ಷಿತ ಪೂರ್ಣಗೊಳ್ಳುವ ಸಮಯ: 4 ಗಂಟೆಗಳು. ಮೆಟ್ಟಿಲುಗಳು ಯಾವಾಗಲೂ ಪ್ರವೇಶಿಸಬಹುದಾಗಿದೆ.',
  'new_visitor_parking_policy': 'ಹೊಸ ಸಂದರ್ಶಕರ ಪಾರ್ಕಿಂಗ್ ನೀತಿ',
  'effective_1_august_2026_visitor_parking_is_limited_to_2_hours_per_visit_between_9_am_and_9_pm_residents_must_pre_register_visitors_via_the_portal': '1 ಆಗಸ್ಟ್ 2026 ರಿಂದ ಜಾರಿಗೆ ಬರುವಂತೆ, ಬೆಳಿಗ್ಗೆ 9 ರಿಂದ ರಾತ್ರಿ 9 ರ ನಡುವೆ ಸಂದರ್ಶಕರ ಪಾರ್ಕಿಂಗ್ ಅನ್ನು ಪ್ರತಿ ಭೇಟಿಗೆ 2 ಗಂಟೆಗಳವರೆಗೆ ಸೀಮಿತಗೊಳಿಸಲಾಗಿದೆ. ನಿವಾಸಿಗಳು ಪೋರ್ಟಲ್ ಮೂಲಕ ಸಂದರ್ಶಕರನ್ನು ಮೊದಲೇ ನೋಂದಾಯಿಸಿಕೊಳ್ಳಬೇಕು.',
  'fitness_center_new_timings': 'ಫಿಟ್‌ನೆಸ್ ಸೆಂಟರ್ ಹೊಸ ಸಮಯಗಳು',
  'starting_1_august_the_fitness_center_will_be_open_5_am_11_pm_on_weekdays_and_6_am_10_pm_on_weekends_personal_trainers_available_on_sat_sun': 'ಆಗಸ್ಟ್ 1 ರಿಂದ, ಫಿಟ್‌ನೆಸ್ ಸೆಂಟರ್ ವಾರದ ದಿನಗಳಲ್ಲಿ ಬೆಳಿಗ್ಗೆ 5 ರಿಂದ ರಾತ್ರಿ 11 ರವರೆಗೆ ಮತ್ತು ವಾರಾಂತ್ಯದಲ್ಲಿ ಬೆಳಿಗ್ಗೆ 6 ರಿಂದ ರಾತ್ರಿ 10 ರವರೆಗೆ ತೆರೆದಿರುತ್ತದೆ. ಶನಿವಾರ ಮತ್ತು ಭಾನುವಾರದಂದು ವೈಯಕ್ತಿಕ ತರಬೇತುದಾರರು ಲಭ್ಯವಿರುತ್ತಾರೆ.',
  'water_conservation_drive_july_2026': 'ಜಲ ಸಂರಕ್ಷಣಾ ಅಭಿಯಾನ – ಜುಲೈ 2026',
  'we_are_partnering_with_the_local_municipality_for_a_water_conservation_initiative_please_report_leakages_immediately_and_avoid_unnecessary_usage_between_2_pm_5_pm': 'ನಾವು ಜಲ ಸಂರಕ್ಷಣಾ ಉಪಕ್ರಮಕ್ಕಾಗಿ ಸ್ಥಳೀಯ ಪುರಸಭೆಯೊಂದಿಗೆ ಸಹಭಾಗಿತ್ವ ಹೊಂದಿದ್ದೇವೆ. ದಯವಿಟ್ಟು ಸೋರಿಕೆಯನ್ನು ತಕ್ಷಣ ವರದಿ ಮಾಡಿ ಮತ್ತು ಮಧ್ಯಾಹ್ನ 2 ರಿಂದ ಸಂಜೆ 5 ರ ನಡುವೆ ಅನಗತ್ಯ ಬಳಕೆಯನ್ನು ತಪ್ಪಿಸಿ.',
